mod solution;

use solution::Solution;

fn main() {
    let s = vec![
        String::from(
            "!\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~ ",
        ),
        String::from("abcabcbb"),
    ];

    let result: Vec<i32> = s
        .iter()
        .map(|s| Solution::length_of_longest_substring(s.to_string()))
        .collect();
    println!("{:?}", result);
}
